const all = [];
for (const it of $input.all()) { for (const k of (it.json.keys || [])) { all.push(k); } }
// 2026-10-08 00:00 Europe/Warsaw (CEST, UTC+2)
const start = Date.UTC(2026, 9, 8) / 1000 - 7200;
const end = start + 86400;
function today(ts) { return typeof ts === 'number' && ts >= start && ts < end; }
function nm(k) { const n = k.key_name; if (n && typeof n === 'object') { return n.web || n.other || n.ios || n.android; } return n; }
function trToday(k) { const out = []; for (const t of (k.translations || [])) { const v = Date.parse(String(t.modified_at || '').replace(' (Etc/UTC)', 'Z').replace(' ', 'T')) / 1000; if (today(v)) { out.push(t.language_iso); } } return out; }
function brief(k) { return { id: k.key_id, name: nm(k), created: k.created_at, modified: k.modified_at, tr_modified: k.translations_modified_at, langs_today: trToday(k), tags: k.tags }; }
const live = all.filter(function (k) { return !k.is_archived; });
const created = live.filter(function (k) { return today(k.created_at_timestamp); });
const old = live.filter(function (k) { return !today(k.created_at_timestamp); });
const upd = old.filter(function (k) { return today(k.modified_at_timestamp) || today(k.translations_modified_at_timestamp) || trToday(k).length > 0; });
const archivedToday = all.filter(function (k) { return k.is_archived && (today(k.modified_at_timestamp) || today(k.created_at_timestamp)); });
return [{ json: { total_keys: all.length, pages: $input.all().length, created_today_count: created.length, created_today: created.map(brief), updated_today_count: upd.length, updated_today: upd.map(brief), archived_touched_today: archivedToday.map(brief) } }];

const r = $input.first().json;
const EXPECTED = 3;
if (r.created_today_count !== EXPECTED) { throw new Error('Expected ' + EXPECTED + ' keys created today, found ' + r.created_today_count + ' - aborting'); }
const ids = r.created_today.map(function (k) { return k.id; });
return [{ json: { body: { keys: ids.map(function (id) { return { key_id: id, tags: ['081026'], merge_tags: true }; }) } } }];

const r = $input.first().json;
const b = r.body || {};
const keys = b.keys || [];
const tagged = keys.filter(function (k) { return (k.tags || []).indexOf('081026') >= 0; });
return [{ json: { status: r.statusCode, returned: keys.length, tagged: tagged.length, errors: b.errors || null, error: b.error || null, sample_tags: keys.slice(0, 3).map(function (k) { return k.tags; }) } }];
